// Only Veritas knows the token: anything else posting to this webhook is ignored.
const req = $input.first().json;
if ((req.headers || {})['x-veritas-token'] !== '__AUTOMATION_TOKEN__') return [];
const p = req.body;
const critical = p.findings.filter(f => f.severity === 'critical').length;
const subject = p.event === 'test' ? 'Test alert'
  : critical ? `${critical} critical issue(s)` : `${p.findings.length} issue(s)`;
// Only a short summary leaves Veritas: no document content or files; the link needs a sign-in.
return [{ json: {
  kind: p.event === 'test' ? 'test' : 'review_needed',
  organization_id: p.organization_id,
  title: `${subject} to review on ${p.document.number || p.document.filename}`,
  body: p.findings.map(f => `- [${f.severity.toUpperCase()}] ${f.claim}` + (f.impact ? ` (${f.impact} ${f.currency || ''})` : '')).join('\n'),
  link: p.dashboard_url,
  email_mode: p.email_mode, recipients: p.recipients || [], delivery_ids: p.delivery_ids || [],
}}];

// Veritas decides; n8n delivers. email_mode comes from Veritas settings (off | preview | send).
return $input.all()
  .map(i => i.json)
  .filter(m => m.email_mode === 'send' && (m.recipients || []).length)
  .map(m => ({ json: { ...m, to: m.recipients.join(', ') } }));

const sent = $('Email only in send mode').all();
return $input.all().map((item, i) => {
  const out = item.json, ids = sent[i].json.delivery_ids;
  if (out.error) return { json: { delivery_ids: ids, status: 'failed', error: String(out.error.message || out.error).slice(0, 400) } };
  if (Array.isArray(out.accepted) && out.accepted.length) return { json: { delivery_ids: ids, status: 'sent' } };
  return { json: { delivery_ids: ids, status: 'skipped', error: 'The email node is disabled or not configured in n8n: add SMTP credentials and enable it.' } };
});

// Preview mode: report what WOULD have been emailed, without sending anything.
return $input.all()
  .map(i => i.json)
  .filter(m => !(m.email_mode === 'send' && (m.recipients || []).length))
  .map(m => ({ json: {
    delivery_ids: m.delivery_ids,
    status: m.email_mode === 'preview' ? 'preview' : 'skipped',
    error: m.email_mode === 'preview'
      ? `Preview only, not sent. Would email ${(m.recipients || []).join(', ') || 'nobody (no recipients set)'}: ${m.title}`
      : (m.email_mode === 'send' ? 'No recipients set' : 'Email is off for this organization'),
  } }));
